INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall nur für externe Angriffe relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Bedrohungen abwehrbar"}, {"text": "Ja", "correct": false, "because": "Umfassender Schutz möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Firewall-Konfiguration?', 3, '[{"text": "Netzwerksicherheit", "correct": true, "because": "Schutz vor unbefugtem Zugriff"}, {"text": "Datenmenge maximieren", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sicherheit im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen erfüllt eine Firewall?', 5, '[{"text": "Paketfilterung", "correct": true, "because": "Kontrolliert Datenverkehr"}, {"text": "Statusprüfung", "correct": true, "because": "Stateful Inspection"}, {"text": "Datenbankdesign", "correct": false, "because": "Nicht relevant"}, {"text": "Visuelle Gestaltung", "correct": false, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Firewalls blockieren unerlaubten Zugriff. b) Sie schützen vor internen Bedrohungen vollends.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Interne Bedrohungen teilweise ausgenommen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Firewall-Konfiguration?', 4, '[{"text": "Regeldefinition", "correct": false, "because": "Kern der Konfiguration"}, {"text": "Portfreigaben", "correct": false, "because": "Steuert Zugriff"}, {"text": "Farbschema", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Firewall auch Protokolle überprüft?', 2, '[{"text": "Ja", "correct": true, "because": "Application Layer Filtering möglich"}, {"text": "Nein", "correct": false, "because": "Moderne Firewalls tun das"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Firewall schützt vor externen Angriffen?', 3, '[{"text": "Stateful Firewall", "correct": true, "because": "Prüft Verbindungsstatus"}, {"text": "Statische IPs", "correct": false, "because": "Kein Firewall-Typ"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellungen sind bei einer Firewall wichtig?', 5, '[{"text": "Zugriffsregeln", "correct": true, "because": "Definiert erlaubten Verkehr"}, {"text": "Logging", "correct": true, "because": "Protokolliert Ereignisse"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Animationseffekte", "correct": false, "because": "Kein Schutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Firewalls schützen vor DDoS-Angriffen. b) Sie sind nur für große Netzwerke nötig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Netzwerke profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Firewall-Konfiguration?', 4, '[{"text": "IP-Filter", "correct": false, "because": "Steuert Zugriff"}, {"text": "Protokollregeln", "correct": false, "because": "Definiert Verkehr"}, {"text": "Grafisches Design", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Schützt eine Firewall auch vor Viren?', 2, '[{"text": "Nein", "correct": true, "because": "Nur Netzwerkebene, keine Inhalte"}, {"text": "Ja", "correct": false, "because": "Antivirus ist separat"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von Firewalls gibt es?', 4, '[{"text": "Paketfilter", "correct": true, "because": "Grundlegender Typ"}, {"text": "Next-Generation", "correct": true, "because": "Erweiterte Funktionen"}, {"text": "Datenbankserver", "correct": false, "because": "Kein Firewall-Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine Firewall alles blockiert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Nur nach Regeln blockiert"}, {"text": "Ja", "correct": false, "because": "Konfigurierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Firewall-Konfiguration?', 3, '[{"text": "Sicherheitsregeln", "correct": true, "because": "Bestimmt Schutzlevel"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Sekundär"}, {"text": "Visuelles Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Firewalls filtern Datenverkehr. b) Sie ersetzen Antivirenprogramme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Antivirus ist separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützt eine Firewall?', 5, '[{"text": "Port-Blockierung", "correct": true, "because": "Verhindert Zugriff"}, {"text": "IP-Whitelisting", "correct": true, "because": "Erlaubt bestimmte Quellen"}, {"text": "Maximale Speicherung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Datenbankdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Firewall-Konfiguration unwichtig?', 3, '[{"text": "Regelwartung", "correct": false, "because": "Sichert Effektivität"}, {"text": "Protokollierung", "correct": false, "because": "Überwacht Aktivitäten"}, {"text": "Schriftarten", "correct": true, "because": "Kein Sicherheitsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Firewall interne Angriffe stoppen?', 3, '[{"text": "Ja", "correct": true, "because": "Mit richtiger Konfiguration möglich"}, {"text": "Nein", "correct": false, "because": "Nicht nur extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Firewall regelmäßig aktualisiert werden muss?', 2, '[{"text": "Ja", "correct": true, "because": "Schutz vor neuen Bedrohungen"}, {"text": "Nein", "correct": false, "because": "Updates nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine Firewall-Konfiguration?', 4, '[{"text": "Zugriffsregeln", "correct": true, "because": "Definiert erlaubten Verkehr"}, {"text": "Zufällige Daten", "correct": false, "because": "Irrelevant"}, {"text": "Grafisches Design", "correct": false, "because": "Kein Schutzfokus"}]');
